  const levels=[
    ["analysis-building",scope],["analysis-scenario",r=>[r.scenarioKey]],["analysis-resource",r=>[r.resourceKey]],["analysis-reading-type",r=>[r.readingType]],["analysis-units",r=>[r.units]],["analysis-stream",r=>[r.streamKey||""]]
